                    'Air Freight': 19.87,
                    'Sea Freight': 15.00,
                    'Ground': 12.00,
                    'Door to Door': 22.00
                },
                '11-25 kg': {
                    'Air Freight': 16.06,
                    'Sea Freight': 12.00,
                    'Ground': 9.00,
                    'Door to Door': 18.00
                },
                '26-200 kg': {
                    'Air Freight': 13.91,
                    'Sea Freight': 10.00,
                    'Ground': 7.00,
                    'Door to Door': 15.00
                }
            }
            
            if (self.quantity_range in freight_matrix and 
                self.freight_type in freight_matrix[self.quantity_range]):
                self.freight_cost = freight_matrix[self.quantity_range][self.freight_type]

